import sys
import xml.etree.ElementTree as ET
import os
import subprocess

def main():
    if len(sys.argv) != 2:
        print("Usage: python jobrunner.py <config.xml>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print(f"Config file not found: {config_path}", file=sys.stderr)
        sys.exit(1)

    for job in root.findall('job'):
        name = job.get('name')
        command = job.get('command')
        cache_path = job.get('cache')

        if not name or not command or not cache_path:
            print(f"Invalid job element: missing required attributes", file=sys.stderr)
            sys.exit(1)

        if os.path.exists(cache_path):
            try:
                with open(cache_path, 'rb') as f:
                    result = f.read().decode('utf-8')
            except UnicodeDecodeError:
                print(f"Cache file {cache_path} is not valid UTF-8", file=sys.stderr)
                sys.exit(1)
        else:
            try:
                result = subprocess.check_output(command, shell=True, text=True, stderr=subprocess.STDOUT)
                with open(cache_path, 'wb') as f:
                    f.write(result.encode('utf-8'))
            except subprocess.CalledProcessError as e:
                result = "ERROR"
            except Exception as e:
                print(f"Error executing command: {e}", file=sys.stderr)
                sys.exit(1)

        print(f"--- {name} ---")
        print(result)
        if not result.endswith('\n'):
            print()

if __name__ == "__main__":
    main()
